window.IMPULS_LESSONS_7={
"Что изучает физика":{
title:"Что изучает физика",
lead:"Почему мяч летит по дуге? Отчего тает лёд? Как свет попадает в комнату? Физика помогает находить закономерности в явлениях окружающего мира.",
short:"Физика изучает явления природы, свойства тел и веществ, а также закономерности, по которым происходят изменения и взаимодействия в природе.",
key:"Физика не просто описывает отдельные события — она ищет общие правила, которые помогают объяснять и предсказывать явления.",
explanation:[
"Вокруг нас постоянно происходят изменения: движутся автомобили, звучит музыка, нагревается вода, появляется радуга, притягиваются мелкие металлические предметы к магниту. Такие изменения и процессы называют физическими явлениями.",
"Физика исследует материальный мир: тела, вещества, поля, их свойства, движение и взаимодействие. Наблюдая явления, учёные выдвигают предположения, проводят опыты, измеряют величины и проверяют, повторяется ли найденная закономерность.",
"Важно различать тело, вещество и явление. Стеклянный стакан — физическое тело; стекло — материал (вещество); запотевание холодной поверхности — физическое явление. Один и тот же предмет может участвовать сразу в нескольких физических процессах."
],
groups:[
{name:"Механические",title:"Движение и равновесие",example:"Падение листа, движение велосипеда, качание качелей."},
{name:"Тепловые",title:"Нагревание и охлаждение",example:"Таяние снега, кипение воды, остывание чая."},
{name:"Электрические и магнитные",title:"Заряды и магниты",example:"Молния, работающий электроприбор, притяжение магнитом скрепки."},
{name:"Световые и звуковые",title:"Свет и звук",example:"Отражение в зеркале, тень, эхо и звучание струны."}
],
observations:[
{scene:"Капля воды на холодном стакане",prompt:"Нажми, чтобы увидеть возможное объяснение",answer:"На холодной поверхности водяной пар из воздуха охлаждается и конденсируется в капли. Это тепловое явление."},
{scene:"Мяч после удара меняет скорость",prompt:"Нажми, чтобы увидеть возможное объяснение",answer:"При взаимодействии с ногой на мяч действует сила. Его скорость и направление движения меняются. Это механическое явление."},
{scene:"Ложка нагревается в горячем чае",prompt:"Нажми, чтобы увидеть возможное объяснение",answer:"Энергия передаётся от горячего чая ложке, в том числе за счёт теплопроводности. Это тепловое явление."}
],
practice:"Проведи небольшое наблюдение в комнате или на улице. Найди три разных физических явления и опиши, что меняется и что остаётся прежним.",
steps:["Запиши, что именно ты наблюдаешь.","Определи, какое тело или вещество участвует в явлении.","Опиши, что изменяется: положение, скорость, температура, форма, состояние или другое свойство.","Предположи, что могло вызвать изменение."],
conclusion:"Физическое исследование начинается с внимательного наблюдения и точного вопроса о том, что происходит и почему.",
question:"Какой пример лучше всего показывает, что физика изучает закономерности природы?",
answers:["Запомнить название каждого предмета в комнате","Исследовать, как изменяется скорость падающего мяча и от чего она зависит","Перечислить цвета всех окружающих предметов"],
correct:1
}
,"Некоторые физические термины":{
title:"Некоторые физические термины",paragraph:"§ 2",lead:"Чтобы точно говорить о природе, физики используют общий язык: физическое тело, вещество, явление и физическая величина.",short:"Физическое тело — отдельный предмет; вещество — то, из чего состоят тела; физическое явление — происходящее изменение или процесс; физическая величина — измеряемое свойство.",key:"Не путай предмет, материал, процесс и измеряемое свойство.",explanation:["Физическое тело — любой предмет, который рассматривают при изучении природы. Например, мяч, капля воды, линейка или планета. У тела есть форма, размеры и другие свойства.","Вещество — материал, из которого состоят тела. Один и тот же материал может образовывать разные тела: из стекла делают стаканы, окна и лабораторные пробирки. А одно тело может состоять из нескольких материалов.","Физическое явление — изменение или процесс, который происходит с телами и веществами: движение, нагревание, плавление, распространение света, электризация.","Физическая величина — характеристика тела или явления, которую можно измерить. Например, длина, масса, время, температура, объём и скорость. Результат измерения выражают числом и единицей."],groups:[{name:"Тело",title:"Что рассматриваем?",example:"Стакан, капля воды, автомобиль, Луна."},{name:"Вещество",title:"Из чего сделано?",example:"Стекло, вода, железо, воздух."},{name:"Явление",title:"Что происходит?",example:"Падение, испарение, отражение света."},{name:"Величина",title:"Что можно измерить?",example:"Масса, длина, время, температура."}],observations:[{scene:"Медная проволока",prompt:"Раздели понятия",answer:"Проволока — физическое тело, медь — вещество, из которого она изготовлена."},{scene:"Лёд тает в стакане",prompt:"Что здесь является явлением?",answer:"Плавление льда — физическое явление. Лёд и вода состоят из одного вещества — воды, но находятся в разных агрегатных состояниях."},{scene:"Линейка показывает 12 см",prompt:"Что измерили?",answer:"Измерили длину. 12 — числовое значение, сантиметр — единица длины."}],practice:"Рассмотри три предмета вокруг себя и для каждого назови тело, материал и одну физическую величину, которую можно измерить.",steps:["Выбери предмет.","Назови материал, из которого он сделан.","Выбери измеряемое свойство.","Запиши величину и подходящую единицу измерения."],conclusion:"Точные физические термины помогают не путать предмет, материал, процесс и его количественную характеристику.",question:"Что из перечисленного является физической величиной?",answers:["Стеклянный стакан","Испарение воды","Температура воды"],correct:2
},
"Научные методы изучения природы":{
title:"Научные методы изучения природы",paragraph:"§ 3",lead:"Как учёные узнают, почему происходят явления? Они наблюдают, задают вопросы, выдвигают гипотезы и проверяют их опытом.",short:"Основные методы изучения природы — наблюдение, эксперимент и моделирование. Измерения помогают получать количественные данные.",key:"Наблюдение помогает заметить явление, гипотеза — предложить объяснение, эксперимент — проверить его.",explanation:["Наблюдение — изучение явления в естественных условиях без намеренного изменения хода процесса. Наблюдатель внимательно фиксирует, что происходит, при каких условиях и как меняется результат.","Эксперимент (опыт) — исследование, при котором учёный специально создаёт или изменяет условия и наблюдает результат. Хороший опыт должен быть организован так, чтобы можно было понять, какой фактор повлиял на результат.","Гипотеза — проверяемое предположение о причине явления или связи между величинами. Гипотеза не становится научным фактом только потому, что кажется убедительной: её нужно проверять.","Моделирование используют, когда реальный объект слишком велик, мал, сложен или недоступен. Модель сохраняет важные для исследования свойства, но не обязана повторять объект во всём."],groups:[{name:"Наблюдение",title:"Смотри и фиксируй",example:"Наблюдать, как меняется длина тени в течение дня."},{name:"Эксперимент",title:"Измени условия",example:"Сравнить, как быстро тает лёд в тёплом и прохладном месте."},{name:"Моделирование",title:"Создай модель",example:"Использовать схему движения частиц, чтобы объяснить диффузию."},{name:"Измерение",title:"Получи числа",example:"Измерить время, температуру или длину и сравнить результаты."}],observations:[{scene:"Тень от дерева утром и днём",prompt:"Какой метод подойдёт?",answer:"Можно провести наблюдение: отмечать положение и длину тени в разное время, не изменяя специально условия."},{scene:"Две одинаковые ёмкости с водой",prompt:"Как проверить влияние температуры?",answer:"Поставить ёмкости в разные температурные условия, сохранив остальные условия по возможности одинаковыми, и измерять изменение температуры или объёма испарившейся воды."},{scene:"Модель молекул в приложении",prompt:"Зачем нужна модель?",answer:"Она помогает представить движение частиц, которые нельзя увидеть невооружённым глазом. Модель показывает выбранные свойства, но упрощает реальность."}],practice:"Составь план безопасного опыта: выясни, влияет ли площадь открытой поверхности на скорость испарения воды. Не проводи опыт с нагревательными приборами без разрешения учителя.",steps:["Сформулируй вопрос и гипотезу.","Подготовь две одинаковые ёмкости с одинаковым количеством воды, но разной площадью открытой поверхности.","Поставь их в одинаковые условия.","Через равные промежутки времени сравни изменение уровня воды и запиши наблюдения."],conclusion:"Научный вывод опирается на наблюдения и проверяемые результаты, а не только на догадки.",question:"Какой метод позволяет специально изменить условия и проверить гипотезу?",answers:["Наблюдение","Эксперимент","Случайное предположение"],correct:1
},
"Физические величины. Измерение физических величин":{
title:"Физические величины. Измерение физических величин",paragraph:"§ 4",lead:"Физика не ограничивается словами «быстро», «тяжёлый» или «горячий». Она измеряет свойства и выражает результат числом с единицей.",short:"Физическая величина — измеряемая характеристика тела или явления. Измерить величину — значит сравнить её с единицей измерения с помощью прибора или метода.",key:"Любой результат измерения записывай числом и единицей: например, 15 см, 2 кг, 30 с.",explanation:["Для измерения длины используют линейку или рулетку, массы — весы, времени — часы или секундомер, температуры — термометр. Выбор прибора зависит от того, какую величину нужно измерить и с какой точностью.","В Международной системе единиц (СИ) основная единица длины — метр (м), массы — килограмм (кг), времени — секунда (с), термодинамической температуры — кельвин (К). В повседневных измерениях часто используют также сантиметры, граммы, минуты и градусы Цельсия.","Число без единицы измерения часто неполно: запись «длина 12» не сообщает, измеряли ли длину в миллиметрах, сантиметрах или метрах. Полная запись: «длина 12 см».","Перед измерением проверь нулевую отметку прибора, подходящий диапазон и цену деления шкалы. При измерении линейкой совмести начало предмета с нулём или учти начальное показание шкалы."],groups:[{name:"Длина",title:"Метр (м)",example:"Линейка, рулетка; 1 м = 100 см."},{name:"Масса",title:"Килограмм (кг)",example:"Весы; 1 кг = 1000 г."},{name:"Время",title:"Секунда (с)",example:"Секундомер; 1 мин = 60 с."},{name:"Температура",title:"Кельвин (К)",example:"Термометр; в быту часто используют градусы Цельсия (°C)."}],observations:[{scene:"Измеряем карандаш",prompt:"Как правильно поставить линейку?",answer:"Начало карандаша совмести с нулевой отметкой. Если это невозможно, измерь положение обоих концов и найди разность показаний."},{scene:"На весах 250 г",prompt:"Как записать результат в килограммах?",answer:"250 г = 0,25 кг, потому что 1 кг содержит 1000 г."},{scene:"Секундомер показывает 1:20",prompt:"Сколько это секунд?",answer:"1 мин 20 с = 60 с + 20 с = 80 с."}],practice:"Измерь длину трёх небольших предметов линейкой и запиши результаты с единицами измерения. Затем переведи один результат из сантиметров в миллиметры.",steps:["Выбери линейку с подходящим диапазоном.","Проверь нулевую отметку и цену деления.","Расположи предмет вдоль шкалы.","Запиши результат и единицу измерения; при необходимости укажи, до какого деления удалось измерить."],conclusion:"Измерение связывает наблюдение с числом. Единица и прибор помогают сделать результат понятным и сравнимым.",question:"Как правильно записать результат измерения длины?",answers:["12","12 сантиметров","Сантиметров"],correct:1
},
"Точность и погрешность измерений":{
title:"Точность и погрешность измерений",paragraph:"§ 5",lead:"Любое реальное измерение имеет ограничения. Прибор, способ измерения и действия человека влияют на то, насколько близок результат к истинному значению.",short:"Точность измерения зависит от прибора и способа работы с ним. Погрешность показывает, насколько результат измерения может отличаться от истинного значения.",key:"Не записывай лишние цифры: результат должен соответствовать возможностям измерительного прибора.",explanation:["У каждой шкалы есть цена деления — значение, соответствующее промежутку между соседними отметками. Чем меньше цена деления при прочих равных условиях, тем более мелкие изменения прибор позволяет различать.","На результат могут влиять толщина штрихов, положение глаза относительно шкалы, неровное положение предмета, колебания показаний и особенности самого прибора. При чтении шкалы смотри на неё прямо, чтобы уменьшить ошибку параллакса.","Погрешность — характеристика неопределённости результата измерения. Она не означает, что измерение обязательно выполнено плохо: полностью устранить влияние всех факторов обычно невозможно.","Если измерение повторяют несколько раз, результаты могут немного различаться. Повторные измерения помогают заметить разброс значений и повысить надёжность вывода. Конкретный способ оценки погрешности зависит от прибора и методики, которую задаёт учитель."],groups:[{name:"Цена деления",title:"Шаг шкалы",example:"Между отметками 0 и 1 см десять равных промежутков — цена деления 1 мм."},{name:"Считывание",title:"Смотри прямо",example:"Глаз должен находиться напротив отметки, чтобы уменьшить параллакс."},{name:"Повтор",title:"Сравни результаты",example:"Повтори измерение несколько раз одинаковым способом и сравни показания."}],observations:[{scene:"Две линейки с разными шкалами",prompt:"Какая различает более мелкие изменения?",answer:"Та, у которой меньшая цена деления, при условии исправности и правильного использования."},{scene:"Глаз смотрит на шкалу сбоку",prompt:"Что может произойти?",answer:"Показание может быть считано неверно из-за параллакса — видимого смещения отметки при наблюдении под углом."},{scene:"Повторные измерения немного отличаются",prompt:"Это обязательно означает ошибку ученика?",answer:"Нет. Разброс может возникать из-за ограничений прибора, условий измерения и случайных факторов. Важно аккуратно повторять измерение и описывать результат честно."}],practice:"Сравни измерение одного предмета двумя линейками с разной ценой деления. Запиши цену деления каждой линейки и объясни, какой результат можно считать более детальным.",steps:["Определи цену деления первой линейки.","Измерь предмет, не меняя положения его концов.","Повтори измерение второй линейкой.","Сравни показания и объясни, почему число знаков после запятой должно соответствовать возможностям прибора."],conclusion:"Точный результат — это не просто много цифр, а аккуратное измерение с учётом возможностей прибора и условий опыта.",question:"Что называют ценой деления шкалы?",answers:["Максимальное значение прибора","Значение, соответствующее одному промежутку между соседними отметками","Длину самого прибора"],correct:1
},
"Физика и её влияние на развитие техники":{
title:"Физика и её влияние на развитие техники",paragraph:"§ 6",lead:"От очков и смартфонов до медицинских томографов и космических аппаратов — техника создаётся благодаря пониманию физических законов.",short:"Физические открытия и законы помогают объяснять природные процессы, создавать приборы, машины, средства связи, диагностики и новые технологии.",key:"Техника использует физические закономерности, а новые приборы, в свою очередь, помогают учёным глубже изучать природу.",explanation:["Знания о движении и силах применяют при создании транспорта, мостов, подъёмников и спортивного оборудования. Расчёт прочности и устойчивости помогает делать конструкции надёжными.","Тепловые явления лежат в основе отопления, холодильников, термосов и двигателей. Понимание передачи тепла позволяет сохранять продукты, обогревать помещения и защищать человека от перегрева или охлаждения.","Электрические и магнитные явления используются в электродвигателях, генераторах, освещении, компьютерах и средствах связи. Оптика помогает создавать очки, камеры, микроскопы и телескопы.","Физика важна и для медицины: ультразвук используют для получения изображений внутренних органов, рентгеновское излучение — для диагностики, магнитный резонанс — для получения подробных изображений тканей. Медицинские приборы требуют специальных мер безопасности и подготовки специалистов.","Развитие техники не означает, что любое новое устройство автоматически полезно или безопасно. Инженеры проверяют надёжность, энергопотребление, влияние на человека и окружающую среду."],groups:[{name:"Механика",title:"Транспорт и конструкции",example:"Тормоза автомобиля, лифт, мост, велосипед."},{name:"Тепловые процессы",title:"Сохранение и передача тепла",example:"Термос, холодильник, система отопления."},{name:"Электричество и магнетизм",title:"Энергия и связь",example:"Электродвигатель, генератор, смартфон."},{name:"Оптика и волны",title:"Исследование и диагностика",example:"Микроскоп, очки, ультразвуковой аппарат и медицинская визуализация."}],observations:[{scene:"Термос сохраняет температуру напитка",prompt:"Какие процессы важно учитывать?",answer:"Нужно уменьшить передачу тепла между напитком и окружающей средой: теплопроводность, конвекцию и тепловое излучение."},{scene:"Врач использует ультразвуковой аппарат",prompt:"Какое физическое явление используется?",answer:"Аппарат посылает и принимает ультразвуковые волны. По отражённым сигналам формируется изображение внутренних структур."},{scene:"Электродвигатель вращает вентилятор",prompt:"Какие разделы физики здесь работают?",answer:"Электрические и магнитные явления преобразуют электрическую энергию в механическую; вращение относится к механическому движению."}],practice:"Выбери один технический прибор дома или в школе. Определи, для чего он нужен, какое физическое явление лежит в основе его работы и какие меры безопасного использования важны.",steps:["Назови прибор и его назначение.","Определи, какие физические процессы обеспечивают его работу.","Найди связь между устройством и изученными явлениями.","Запиши одно преимущество и одно требование безопасности."],conclusion:"Физика помогает не только объяснять окружающий мир, но и создавать технологии, которые меняют повседневную жизнь.",question:"Как физика помогает развитию техники?",answers:["Только даёт названия деталям приборов","Позволяет использовать законы природы для создания и совершенствования устройств","Заменяет необходимость проверять безопасность устройств"],correct:1
}
,"Строение веществ":{
title:"Строение веществ",paragraph:"§ 7",chapter:"Глава 1 · Первоначальные сведения о строении вещества",lead:"Вода, воздух, металл и наше тело кажутся сплошными. Но из чего они состоят на самом деле? Физика помогает заглянуть в невидимый мир частиц.",short:"Вещества состоят из мельчайших частиц. Между частицами есть промежутки, а сами частицы находятся в непрерывном движении и взаимодействуют друг с другом.",key:"Вещество не является сплошным на уровне частиц: оно состоит из частиц, между которыми есть промежутки.",explanation:["Обычные тела кажутся сплошными, потому что отдельные частицы очень малы и их невозможно различить невооружённым глазом. Однако многие явления можно объяснить, если представить, что вещество состоит из мельчайших частиц.","Частицы вещества разделены промежутками. Их размеры и расстояния между ними зависят от вещества и агрегатного состояния. В газах промежутки в среднем значительно больше, чем в жидкостях и твёрдых телах.","Частицы не остаются неподвижными. Они непрерывно движутся: в твёрдом теле колеблются около определённых положений, в жидкости перемещаются и меняются местами, а в газе движутся свободно и хаотично.","Частицы взаимодействуют: притягиваются на сравнительно больших расстояниях и резко отталкиваются при сильном сближении. Это помогает объяснить, почему тела сохраняют объём, почему их трудно сжать и почему они могут сопротивляться растяжению."],groups:[{name:"Твёрдое тело",title:"Частицы рядом",example:"Частицы расположены близко и колеблются около устойчивых положений."},{name:"Жидкость",title:"Частицы подвижны",example:"Частицы остаются близко, но могут перемещаться относительно друг друга."},{name:"Газ",title:"Большие промежутки",example:"Частицы движутся хаотично и занимают весь доступный объём."}],observations:[{scene:"Запах распространяется по комнате",prompt:"Как это можно объяснить?",answer:"Частицы вещества движутся хаотично и постепенно перемешиваются с частицами воздуха. Это объяснение опирается на молекулярное строение вещества."},{scene:"Воздух в шприце с закрытым отверстием",prompt:"Почему поршень можно немного вдавить?",answer:"Газ можно сжать, потому что между его частицами сравнительно большие промежутки."},{scene:"Камень сохраняет форму",prompt:"Почему он не растекается?",answer:"В твёрдом теле частицы удерживаются около определённых положений и сильно взаимодействуют друг с другом."}],practice:"Сравни мысленно твёрдое тело, воду и воздух. Нарисуй три схемы расположения частиц и подпиши, как они движутся.",steps:["Изобрази частицы твёрдого тела близко друг к другу и упорядоченно.","Для жидкости сохрани близкое расположение, но покажи возможность перемещения.","Для газа изобрази частицы на больших расстояниях и стрелки хаотического движения.","Сравни схемы и объясни, почему газ легче сжать, чем воду или твёрдое тело."],conclusion:"Модель частиц позволяет объяснить свойства веществ, которые трудно понять только по внешнему виду тел.",question:"Какое утверждение соответствует молекулярному строению вещества?",answers:["Частицы вещества неподвижны и не взаимодействуют","Вещество состоит из частиц, которые движутся и взаимодействуют","Между частицами любого вещества совсем нет промежутков"],correct:1
},
"Молекулы":{
title:"Молекулы",paragraph:"§ 8",chapter:"Глава 1 · Первоначальные сведения о строении вещества",lead:"Мельчайшие частицы вещества могут быть настолько малы, что в крошечной капле воды их огромное количество. Одной из таких частиц является молекула.",short:"Молекула — наименьшая частица вещества, которая сохраняет его основные химические свойства. Молекулы состоят из атомов.",key:"Молекулы одного и того же вещества одинаковы по составу и строению, но разные вещества могут иметь разные молекулы.",explanation:["Молекула — частица, состоящая из атомов, соединённых между собой. Например, молекула воды состоит из двух атомов водорода и одного атома кислорода. Её обозначают H₂O: индекс 2 показывает два атома водорода.","Атомы и молекулы чрезвычайно малы. Поэтому в обычной жизни мы не видим отдельные молекулы, а наблюдаем свойства огромного количества частиц вместе.","Молекулы одного вещества имеют одинаковый химический состав и строение. Молекулы разных веществ могут отличаться составом, размером и формой. Например, молекулы кислорода O₂ состоят из двух атомов кислорода, а молекулы углекислого газа CO₂ — из одного атома углерода и двух атомов кислорода.","При физических явлениях молекулы могут менять расположение, скорость движения и расстояния между ними. При химических превращениях могут изменяться сами молекулы: одни связи разрушаются, другие образуются."],groups:[{name:"H₂O",title:"Молекула воды",example:"Два атома водорода и один атом кислорода."},{name:"O₂",title:"Молекула кислорода",example:"Два атома кислорода."},{name:"CO₂",title:"Молекула углекислого газа",example:"Один атом углерода и два атома кислорода."}],observations:[{scene:"Капля воды и кусочек льда",prompt:"Разные ли у них молекулы?",answer:"И лёд, и жидкая вода состоят из молекул H₂O. Отличаются расположение, движение и взаимодействие молекул, а не химический состав."},{scene:"Кислород в воздухе",prompt:"Из каких частиц состоит молекула кислорода?",answer:"Обычная молекула кислорода O₂ состоит из двух атомов кислорода."},{scene:"Разные запахи духов",prompt:"Почему запахи отличаются?",answer:"Разные ароматические вещества состоят из разных молекул, которые по-разному взаимодействуют с рецепторами обоняния."}],practice:"Составь карточки для трёх молекул: H₂O, O₂ и CO₂. Для каждой укажи, сколько и каких атомов входит в её состав.",steps:["Прочитай химическую формулу.","Найди символы химических элементов.","Посчитай число атомов каждого элемента с учётом индексов.","Нарисуй условную модель молекулы и подпиши, что рисунок не показывает реальные размеры атомов."],conclusion:"Молекулярные модели помогают представить состав вещества, но изображения атомов и связей всегда условны.",question:"Сколько атомов входит в состав одной молекулы воды H₂O?",answers:["Два","Три","Четыре"],correct:1
},
"Броуновское движение":{
title:"Броуновское движение",paragraph:"§ 9",chapter:"Глава 1 · Первоначальные сведения о строении вещества",lead:"Почему крошечные частицы пыльцы или краски в жидкости беспорядочно перемещаются, хотя никто их не толкает рукой?",short:"Броуновское движение — непрерывное хаотическое движение мелких частиц, взвешенных в жидкости или газе, вызванное ударами молекул среды.",key:"Невидимое движение молекул можно обнаружить по беспорядочному движению достаточно малых частиц.",explanation:["В 1827 году ботаник Роберт Броун наблюдал под микроскопом беспорядочное движение мелких частиц пыльцы в воде. Частицы двигались неровно, меняя направление, хотя вода казалась неподвижной.","Объяснение связано с молекулярным строением вещества. Молекулы воды непрерывно и хаотично движутся и ударяют по взвешенной частице с разных сторон. В каждый момент удары с разных сторон не полностью компенсируют друг друга, поэтому частица меняет скорость и направление.","Броуновское движение является свидетельством того, что молекулы среды находятся в непрерывном тепловом движении. Чем выше температура жидкости или газа, тем интенсивнее тепловое движение молекул и обычно тем заметнее броуновское движение при прочих равных условиях.","Не следует путать броуновское движение с обычным перемешиванием жидкости потоком. В первом случае видимая частица беспорядочно движется из-за ударов молекул среды; во втором вещество переносится общим движением жидкости."],groups:[{name:"Молекулы среды",title:"Невидимые участники",example:"Хаотически движутся и ударяют по взвешенной частице со всех сторон."},{name:"Взвешенная частица",title:"То, что видно",example:"Получает неодинаковые удары и движется беспорядочно."},{name:"Температура",title:"Влияние нагрева",example:"При более высокой температуре тепловое движение молекул интенсивнее."}],observations:[{scene:"Частица пыльцы в капле воды",prompt:"Почему она движется?",answer:"Её непрерывно толкают молекулы воды, которые сами находятся в хаотическом тепловом движении."},{scene:"Жидкость нагрели",prompt:"Как изменится движение молекул?",answer:"Средняя кинетическая энергия теплового движения молекул увеличится; при прочих равных условиях броуновское движение обычно станет интенсивнее."},{scene:"Вода движется целым потоком",prompt:"Это обязательно броуновское движение?",answer:"Нет. Если частицы переносятся общим потоком жидкости, это движение вместе с потоком, а не собственно броуновское движение."}],practice:"Представь, что наблюдаешь под микроскопом маленькую частицу в неподвижной воде. Нарисуй несколько последовательных положений частицы и ломаную траекторию, которая показывает изменение направления.",steps:["Нарисуй условную частицу в первом положении.","Отметь несколько следующих положений в разных направлениях.","Добавь вокруг неё множество маленьких стрелок — условные удары молекул воды.","Объясни, почему результирующее действие ударов в каждый момент может быть неравным нулю."],conclusion:"Броуновское движение — наблюдаемое проявление непрерывного хаотического движения молекул.",question:"Что является причиной броуновского движения?",answers:["Только движение воздуха над жидкостью","Неодинаковые удары молекул среды по взвешенной частице","Притяжение частицы к дну сосуда"],correct:1
},
"Диффузия в газах, жидкостях и твёрдых телах":{
title:"Диффузия в газах, жидкостях и твёрдых телах",paragraph:"§ 10",chapter:"Глава 1 · Первоначальные сведения о строении вещества",lead:"Открой флакон духов — и спустя время аромат почувствуют в другой части комнаты. Как частицы вещества находят дорогу сквозь воздух?",short:"Диффузия — взаимное проникновение частиц одного вещества между частицами другого вследствие их хаотического движения.",key:"Диффузия происходит в газах, жидкостях и твёрдых телах; обычно быстрее всего она протекает в газах и медленнее всего — в твёрдых телах.",explanation:["Если рядом с открытым флаконом духов находится человек, запах не остаётся только около флакона. Частицы ароматического вещества перемешиваются с частицами воздуха. Это явление называют диффузией.","Диффузия возможна в газах, жидкостях и твёрдых телах. В газах частицы движутся быстро и находятся на сравнительно больших расстояниях, поэтому перемешивание обычно происходит быстрее. В жидкостях диффузия идёт медленнее, а в твёрдых телах — очень медленно.","С повышением температуры движение частиц обычно становится интенсивнее, поэтому диффузия ускоряется. Это можно наблюдать, сравнивая распространение капли красителя в холодной и тёплой воде при одинаковых условиях.","В комнате запах распространяется не только за счёт молекулярной диффузии: движение воздуха, сквозняки и конвекция могут значительно ускорять перенос ароматического вещества. Поэтому реальная картина сложнее, чем чистая диффузия в неподвижной среде."],groups:[{name:"Газы",title:"Быстрое перемешивание",example:"Запах распространяется в воздухе; газовые смеси перемешиваются."},{name:"Жидкости",title:"Медленнее",example:"Капля красителя постепенно распределяется в воде даже без перемешивания."},{name:"Твёрдые тела",title:"Очень медленно",example:"При длительном контакте некоторые вещества постепенно проникают друг в друга."}],observations:[{scene:"Капля красителя в стакане воды",prompt:"Почему цвет постепенно распространяется?",answer:"Молекулы красителя и воды хаотически движутся и взаимно проникают друг между другом. Это диффузия."},{scene:"Краситель в тёплой и холодной воде",prompt:"Где обычно перемешивание быстрее?",answer:"В более тёплой воде, потому что тепловое движение частиц интенсивнее. Для честного сравнения не перемешивай стаканы и используй одинаковое количество красителя."},{scene:"Запах в комнате при открытом окне",prompt:"Почему запах может распространиться быстрее?",answer:"Помимо диффузии, воздух движется потоком и переносит ароматические частицы. Это уже совместное действие диффузии и переноса воздуха."}],practice:"Проведи безопасное наблюдение с каплей пищевого красителя в двух прозрачных стаканах: один с прохладной, другой с тёплой водой. Не пробуй воду и не используй горячую воду.",steps:["Налей одинаковое количество воды в два стакана; один пусть будет с прохладной, другой — с тёплой водой.","Одновременно добавь по одной одинаковой капле пищевого красителя, не перемешивая.","Наблюдай, как меняется распределение цвета.","Сравни результаты и укажи, какие условия могли повлиять на скорость диффузии."],conclusion:"Диффузия показывает, что частицы вещества находятся в непрерывном хаотическом движении; повышение температуры обычно ускоряет это явление.",question:"В каком случае диффузия обычно протекает быстрее?",answers:["В твёрдом теле при низкой температуре","В газе при более высокой температуре","Во всех средах с одинаковой скоростью"],correct:1
},
"Взаимное притяжение и отталкивание молекул":{
title:"Взаимное притяжение и отталкивание молекул",paragraph:"§ 11",chapter:"Глава 1 · Первоначальные сведения о строении вещества",lead:"Почему капля воды собирается в комочек, а твёрдое тело сопротивляется сжатию? Между молекулами действуют силы притяжения и отталкивания.",short:"Молекулы взаимодействуют друг с другом: притягиваются на некоторых расстояниях и отталкиваются при очень сильном сближении.",key:"Молекулярное взаимодействие зависит от расстояния между частицами: при одних расстояниях преобладает притяжение, при других — отталкивание.",explanation:["Молекулы не только движутся, но и взаимодействуют. Если расстояние между ними сравнительно велико, заметнее проявляется притяжение. Благодаря этому частицы вещества удерживаются вместе.","При сильном сближении молекул резко возрастает отталкивание. Поэтому твёрдые тела и жидкости трудно сжать: их частицы уже расположены близко, и дальнейшее сближение требует значительного воздействия.","Притяжение молекул можно заметить по тому, что кусочки одного вещества могут сцепляться, а капли жидкости стремятся уменьшить площадь своей поверхности. Однако наблюдаемая форма капли зависит также от тяжести и взаимодействия жидкости с поверхностью.","Силы межмолекулярного взаимодействия действуют на очень малых расстояниях. Их не следует представлять как пружинки между молекулами: рисунки со стрелками — лишь условная модель направления и характера взаимодействия."],groups:[{name:"Притяжение",title:"Частицы удерживаются вместе",example:"Капля сохраняет целостность; тела сопротивляются разделению."},{name:"Отталкивание",title:"Не дают сильно сблизиться",example:"Твёрдое тело и жидкость трудно сжать."},{name:"Равновесное расстояние",title:"Баланс взаимодействия",example:"На определённом расстоянии притяжение и отталкивание уравновешивают друг друга."}],observations:[{scene:"Две капли воды сливаются",prompt:"Почему капли могут объединиться?",answer:"Молекулы воды взаимодействуют, и при сближении капель между ними действуют силы притяжения."},{scene:"Пытаемся сжать воду в закрытом шприце",prompt:"Почему объём меняется мало?",answer:"Молекулы жидкости расположены близко. При попытке сильно сблизить их резко возрастает отталкивание."},{scene:"Твёрдый предмет сохраняет форму",prompt:"Какую роль играет взаимодействие?",answer:"Взаимодействие частиц помогает удерживать их около определённых положений и сопротивляться изменению формы."}],practice:"Сделай две схемы: на первой частицы расположены на сравнительно большом расстоянии, на второй — слишком близко. Стрелками покажи, какое взаимодействие будет преобладать.",steps:["Изобрази две молекулы на некотором расстоянии и стрелки притяжения навстречу друг другу.","Изобрази молекулы очень близко и стрелки отталкивания в противоположные стороны.","Подпиши, что рисунок условный и не показывает реальные масштабы.","Объясни, почему жидкость трудно сжать."],conclusion:"Свойства вещества зависят не только от движения частиц, но и от сил взаимодействия между ними.",question:"Что происходит при очень сильном сближении молекул?",answers:["Всегда исчезает взаимодействие","Резко возрастает отталкивание","Молекулы перестают двигаться"],correct:1
},
"Агрегатные состояния вещества":{
title:"Агрегатные состояния вещества",paragraph:"§ 12",chapter:"Глава 1 · Первоначальные сведения о строении вещества",lead:"Вода может быть льдом, жидкостью и паром. Вещество одно, но его свойства и расположение частиц различаются.",short:"Основные агрегатные состояния вещества в школьном курсе — твёрдое, жидкое и газообразное. Они отличаются расположением, движением и взаимодействием частиц.",key:"При переходе из одного агрегатного состояния в другое молекулы вещества обычно остаются теми же, но меняются их движение, расположение и взаимодействие.",explanation:["В твёрдом состоянии тело сохраняет собственные форму и объём. Частицы расположены близко и колеблются около определённых положений. В кристаллических телах расположение частиц имеет упорядоченный характер.","Жидкость сохраняет объём, но принимает форму сосуда. Частицы находятся близко друг к другу, однако могут перемещаться и менять соседей. Поэтому жидкость течёт.","Газ не сохраняет ни собственную форму, ни собственный объём: он занимает весь доступный сосуд. Частицы находятся далеко друг от друга по сравнению с их размерами и движутся хаотически.","Одно и то же вещество может переходить из состояния в состояние. Лёд плавится и становится водой; вода испаряется и превращается в водяной пар; пар при охлаждении конденсируется. При этом молекулы воды остаются молекулами H₂O."],groups:[{name:"Твёрдое",title:"Сохраняет форму и объём",example:"Лёд, камень, металлическая ложка."},{name:"Жидкое",title:"Сохраняет объём, меняет форму",example:"Вода, масло, молоко."},{name:"Газообразное",title:"Заполняет весь сосуд",example:"Воздух, водяной пар, кислород."}],observations:[{scene:"Лёд тает в стакане",prompt:"Что изменяется?",answer:"Вещество переходит из твёрдого состояния в жидкое. Молекулы остаются H₂O, но меняются их движение и расположение."},{scene:"Вода испаряется с поверхности",prompt:"Куда уходит вода?",answer:"Часть молекул покидает жидкость и переходит в газообразное состояние — водяной пар."},{scene:"Капли на холодном окне",prompt:"Откуда они появились?",answer:"Водяной пар из воздуха охладился у поверхности и сконденсировался в жидкую воду."}],practice:"Составь схему круговорота состояний воды: лёд → жидкая вода → водяной пар → жидкая вода. Подпиши названия переходов.",steps:["Нарисуй три состояния воды.","Соедини их стрелками в нужном порядке.","Подпиши переходы: плавление, испарение и конденсация.","Для каждого состояния опиши расположение и движение молекул."],conclusion:"Агрегатное состояние определяется характером движения, расположения и взаимодействия частиц вещества.",question:"Какое утверждение верно для жидкости?",answers:["Сохраняет собственную форму и объём","Сохраняет объём, но принимает форму сосуда","Всегда заполняет весь объём сосуда"],correct:1
},
"Различие в молекулярном строении твёрдых тел, жидкостей и газов":{
title:"Различие в молекулярном строении твёрдых тел, жидкостей и газов",paragraph:"§ 13",chapter:"Глава 1 · Первоначальные сведения о строении вещества",lead:"Почему камень сохраняет форму, вода растекается, а воздух заполняет комнату? Сравним модели частиц трёх состояний.",short:"Различия между твёрдыми телами, жидкостями и газами объясняются расположением частиц, расстояниями между ними, характером движения и взаимодействием.",key:"Не только расстояние между частицами, но и их подвижность и взаимодействие определяют свойства вещества.",explanation:["В твёрдых телах частицы расположены близко друг к другу и сильно взаимодействуют. Они не перемещаются свободно по всему телу, а колеблются около определённых положений. Поэтому твёрдое тело сохраняет форму и объём.","В жидкостях частицы также находятся близко, но могут перемещаться относительно друг друга. Жидкость сохраняет объём, однако не сохраняет собственную форму и принимает форму сосуда.","В газах расстояния между частицами значительно больше их размеров, а взаимодействие между ними в обычных условиях проявляется главным образом во время сближений. Частицы свободно и хаотично движутся, поэтому газ распространяется и заполняет сосуд.","Молекулярная модель объясняет сжимаемость газов: между частицами газа много свободного пространства. Жидкости и твёрдые тела сжимаются намного труднее, потому что их частицы расположены близко.","Модели частиц являются упрощёнными. Размеры точек, расстояния и скорость движения на рисунках не соответствуют реальному масштабу; они нужны, чтобы сравнить качественные особенности строения."],groups:[{name:"Твёрдое тело",title:"Устойчивое расположение",example:"Частицы колеблются около положений равновесия; тело сохраняет форму и объём."},{name:"Жидкость",title:"Близко, но подвижно",example:"Частицы могут перемещаться; жидкость сохраняет объём и принимает форму сосуда."},{name:"Газ",title:"Далеко и свободно",example:"Частицы движутся хаотически; газ занимает весь доступный объём и легко сжимается."}],observations:[{scene:"Камень, вода и воздух в закрытой комнате",prompt:"Что различается в их строении?",answer:"В камне частицы удерживаются около определённых положений; в воде остаются близко, но перемещаются; в воздухе находятся на больших расстояниях и движутся свободно."},{scene:"Сжимаем воздух в шприце",prompt:"Почему это возможно?",answer:"Частицы газа находятся далеко друг от друга, поэтому расстояния между ними можно уменьшить."},{scene:"Переливаем воду из стакана в бутылку",prompt:"Почему вода меняет форму, но не исчезает?",answer:"Жидкость принимает форму нового сосуда, сохраняя примерно тот же объём."}],practice:"Сравни три состояния по четырём признакам: расстояние между частицами, характер движения, сила взаимодействия и способность сохранять форму/объём.",steps:["Заполни строку для твёрдого тела.","Сравни с жидкостью: что остаётся похожим, а что меняется?","Заполни строку для газа.","По таблице объясни сжимаемость воздуха и текучесть воды."],conclusion:"Макроскопические свойства вещества можно объяснять через движение и взаимодействие огромного числа его частиц.",question:"Почему газ легче сжать, чем жидкость?",answers:["Частицы газа неподвижны","Между частицами газа сравнительно большие промежутки","Молекулы газа исчезают при сжатии"],correct:1
}
,"Механическое движение":{
title:"Механическое движение",paragraph:"§ 14",chapter:"Глава 2 · Взаимодействие тел",lead:"По дороге едет автобус, Земля вращается, кровь движется по сосудам. Во всех этих случаях положение тела меняется относительно других тел.",short:"Механическое движение — изменение положения тела относительно других тел с течением времени.",key:"Чтобы говорить о движении, нужно указать, относительно какого тела рассматривают изменение положения.",explanation:["Тело называют движущимся, если с течением времени оно меняет своё положение относительно других тел. Например, пассажир сидит в автобусе и неподвижен относительно сиденья, но движется относительно дороги.","Тело, относительно которого рассматривают положение и движение, называют телом отсчёта. Одно и то же тело может быть неподвижным относительно одного тела отсчёта и двигаться относительно другого.","Линия, вдоль которой движется тело, называется траекторией. Длина траектории — пройденный путь. Траектория может быть прямой или кривой.","В медицине движение тоже имеет большое значение: кровь перемещается по сосудам, грудная клетка движется при дыхании, медицинская тележка перемещается по коридору. Для описания каждого движения выбирают подходящее тело отсчёта."],groups:[{name:"Тело отсчёта",title:"Относительно чего сравниваем",example:"Дорога, здание, вагон, лабораторный стол."},{name:"Траектория",title:"Линия движения",example:"Прямая дорога или дуга полёта мяча."},{name:"Путь",title:"Длина траектории",example:"Расстояние, которое прошёл велосипедист."}],observations:[{scene:"Пассажир в движущемся автобусе",prompt:"Неподвижен ли пассажир?",answer:"Относительно сиденья — да; относительно дороги — нет. Движение зависит от выбранного тела отсчёта."},{scene:"Мяч летит к корзине",prompt:"Как выглядит траектория?",answer:"При обычном броске траектория мяча имеет криволинейную форму."},{scene:"Кровь движется по сосуду",prompt:"Что можно выбрать телом отсчёта?",answer:"Можно рассматривать движение крови относительно стенок сосуда."}],practice:"Выбери три движущихся объекта вокруг себя. Для каждого укажи тело отсчёта и предположи форму траектории.",steps:["Назови движущийся объект.","Укажи, относительно чего рассматриваешь его движение.","Опиши траекторию: прямая, кривая или более сложная.","Объясни, почему без тела отсчёта нельзя однозначно сказать, движется объект или покоится."],conclusion:"Механическое движение — относительное изменение положения тела. Для его описания необходимо выбрать тело отсчёта.",question:"Пассажир сидит в движущемся автобусе. Какое утверждение верно?",answers:["Он неподвижен относительно дороги","Он движется относительно сиденья","Он неподвижен относительно сиденья и движется относительно дороги"],correct:2
},
"Равномерное и неравномерное движение":{
title:"Равномерное и неравномерное движение",paragraph:"§ 15",chapter:"Глава 2 · Взаимодействие тел",lead:"Автомобиль может ехать с постоянной скоростью, разгоняться и тормозить. По изменению скорости различают виды движения.",short:"При равномерном движении тело за равные промежутки времени проходит равные пути. При неравномерном — за равные промежутки времени проходят разные пути.",key:"Сравнивай пути за одинаковые промежутки времени: так можно определить, равномерно ли движение.",explanation:["Равномерным называют движение, при котором за любые равные промежутки времени тело проходит одинаковые пути. В школьных задачах такое движение рассматривают как движение с постоянной скоростью.","При неравномерном движении за равные промежутки времени тело проходит разные пути. Так происходит, например, при разгоне автомобиля, торможении велосипеда или изменении скорости лифта.","В реальной жизни идеально равномерное движение встречается редко. Даже автомобиль на ровной дороге немного меняет скорость. Модель равномерного движения помогает упростить расчёты, если изменения скорости несущественны.","Чтобы сравнить движение, удобно разбить время на одинаковые интервалы и измерить путь за каждый из них. Если пути одинаковы, движение равномерное; если различаются — неравномерное."],groups:[{name:"Равномерное",title:"Одинаковый путь за равное время",example:"Конвейерная лента движется с постоянной скоростью."},{name:"Неравномерное",title:"Путь за равное время меняется",example:"Автобус разгоняется после остановки."}],observations:[{scene:"Игрушечная машинка проходит 20 см каждую секунду",prompt:"Какой это вид движения?",answer:"Если за каждую секунду машинка проходит одинаковые 20 см, движение равномерное."},{scene:"Велосипедист за первую секунду проехал 2 м, за следующую — 4 м",prompt:"Что можно заключить?",answer:"За равные промежутки времени пройдены разные пути, значит движение неравномерное."}],practice:"Понаблюдай за движением объекта и запиши, одинаковые ли расстояния он проходит за равные интервалы времени.",steps:["Выбери движущийся объект.","Раздели наблюдение на несколько равных промежутков времени.","Сравни пройденные за них пути.","Сделай вывод о характере движения."],conclusion:"Вид движения определяют по тому, какие пути тело проходит за равные промежутки времени.",question:"Тело за каждую секунду проходит 3 метра. Как движется тело?",answers:["Равномерно","Неравномерно","Определить невозможно"],correct:0
},
"Скорость. Единицы скорости":{
title:"Скорость. Единицы скорости",paragraph:"§ 16",chapter:"Глава 2 · Взаимодействие тел",lead:"Два велосипедиста за одно и то же время могут проехать разные расстояния. Скорость показывает, насколько быстро движется тело.",short:"Скорость при равномерном движении равна отношению пройденного пути ко времени, за которое этот путь пройден.",key:"Скорость показывает путь, проходимый телом за единицу времени.",explanation:["Скорость — физическая величина, характеризующая быстроту движения. Если тело за короткое время проходит большой путь, его скорость больше.","Для равномерного движения скорость вычисляют по формуле: v = s / t. Здесь v — скорость (метр в секунду, м/с); s — пройденный путь (метр, м); t — время движения (секунда, с).","Основная единица скорости в Международной системе единиц — метр в секунду (м/с). В повседневной жизни часто используют километр в час (км/ч). Чтобы перевести км/ч в м/с, значение делят на 3,6. Например, 36 км/ч = 10 м/с.","Скорость 5 м/с означает, что при равномерном движении тело проходит 5 метров за каждую секунду. Важно не путать скорость с путём: путь показывает, сколько пройдено, а скорость — насколько быстро это происходило."],groups:[{name:"Формула",title:"v = s / t",example:"Скорость равна пути, делённому на время."},{name:"Единица СИ",title:"м/с",example:"5 м/с — пять метров за одну секунду."},{name:"Другая единица",title:"км/ч",example:"Автомобильный спидометр обычно показывает км/ч."}],observations:[{scene:"Пешеход прошёл 100 м за 50 с",prompt:"Как найти скорость?",answer:"Нужно разделить путь на время: 100 м / 50 с = 2 м/с."},{scene:"Автомобиль движется со скоростью 72 км/ч",prompt:"Сколько это в м/с?",answer:"72 делим на 3,6. Получаем 20 м/с."}],practice:"Рассчитай скорость, если ученик прошёл 60 м за 40 с. Запиши формулу, подстановку чисел и единицу ответа.",steps:["Запиши известные величины: путь и время.","Выбери формулу v = s / t.","Подставь значения с единицами измерения.","Выполни вычисление и запиши ответ в м/с."],conclusion:"Скорость связывает путь и время и позволяет сравнивать быстроту движения разных тел.",question:"Какова скорость тела, если оно прошло 30 м за 5 с?",answers:["6 м/с","25 м/с","150 м/с"],correct:0
},
"Расчёт пути и времени движения":{
title:"Расчёт пути и времени движения",paragraph:"§ 17",chapter:"Глава 2 · Взаимодействие тел",lead:"Если известна скорость движения, можно рассчитать, какое расстояние тело пройдёт за заданное время и сколько времени займёт путь.",short:"При равномерном движении путь равен произведению скорости на время, а время — отношению пути к скорости.",key:"Из формулы скорости можно получить три взаимосвязанные формулы: v = s / t; s = v · t; t = s / v.",explanation:["Скорость, путь и время связаны формулой v = s / t. Из неё можно выразить любую из трёх величин, если две другие известны.","Путь: s = v · t. Здесь s — путь (м), v — скорость (м/с), t — время (с). Например, за 10 с тело со скоростью 3 м/с пройдёт 30 м.","Время: t = s / v. Здесь t — время (с), s — путь (м), v — скорость (м/с). Если нужно пройти 100 м со скоростью 2 м/с, потребуется 50 с.","Перед вычислением проверь единицы. Если скорость дана в км/ч, а время — в секундах, сначала приведи величины к согласованным единицам. Формулы в этом уроке применяются к равномерному движению."],groups:[{name:"Найти путь",title:"s = v · t",example:"Умножь скорость на время."},{name:"Найти время",title:"t = s / v",example:"Раздели путь на скорость."},{name:"Проверка единиц",title:"м/с и с дают метры",example:"(м/с) · с = м."}],observations:[{scene:"Робот движется 4 с со скоростью 2 м/с",prompt:"Какой путь он пройдёт?",answer:"s = 2 м/с · 4 с = 8 м."},{scene:"Дрон должен пролететь 120 м со скоростью 6 м/с",prompt:"Сколько займёт полёт?",answer:"t = 120 м / 6 м/с = 20 с."}],practice:"Реши две задачи: 1) велосипедист едет со скоростью 5 м/с в течение 12 с; 2) робот прошёл 45 м со скоростью 3 м/с. Найди путь в первой задаче и время во второй.",steps:["Определи, что требуется найти в каждой задаче.","Выбери подходящую формулу.","Проверь согласованность единиц измерения.","Подставь числа, вычисли и запиши ответ."],conclusion:"При равномерном движении путь и время можно рассчитать, если известна скорость.",question:"Как найти время движения, если известны путь и скорость?",answers:["t = s · v","t = s / v","t = v / s"],correct:1
},
"Прямолинейное равноускоренное движение. Ускорение":{
title:"Прямолинейное равноускоренное движение. Ускорение",paragraph:"§ 18",chapter:"Глава 2 · Взаимодействие тел",lead:"При разгоне автомобиля скорость увеличивается, при торможении — уменьшается. Ускорение помогает описать, как быстро меняется скорость.",short:"При прямолинейном равноускоренном движении скорость за равные промежутки времени изменяется на одинаковую величину. Ускорение характеризует изменение скорости за единицу времени.",key:"Ускорение показывает, на сколько изменяется скорость за одну секунду.",explanation:["Прямолинейным называют движение по прямой линии. Если скорость тела за равные промежутки времени изменяется на одинаковую величину, движение называют равноускоренным.","Ускорение вычисляют по формуле: a = (v − v₀) / t. Здесь a — ускорение (м/с²); v — конечная скорость (м/с); v₀ — начальная скорость (м/с); t — время изменения скорости (с).","Единица ускорения — метр на секунду в квадрате (м/с²). Ускорение 2 м/с² означает, что при таком равноускоренном движении скорость за каждую секунду увеличивается на 2 м/с. Если скорость уменьшается, ускорение направлено противоположно выбранному положительному направлению движения.","Пример: велосипедист увеличил скорость с 2 м/с до 8 м/с за 3 с. a = (8 − 2) / 3 = 2 м/с². В реальных ситуациях ускорение может меняться, но для решения учебных задач часто используют модель постоянного ускорения."],groups:[{name:"Ускорение",title:"Изменение скорости за время",example:"Разгон, торможение, начало движения."},{name:"Формула",title:"a = (v − v₀) / t",example:"Разность конечной и начальной скоростей делят на время."},{name:"Единица",title:"м/с²",example:"Скорость изменяется на столько-то м/с за каждую секунду."}],observations:[{scene:"Скорость выросла с 0 до 6 м/с за 3 с",prompt:"Чему равно ускорение?",answer:"a = (6 − 0) / 3 = 2 м/с²."},{scene:"Машина тормозит",prompt:"Уменьшается ли модуль скорости?",answer:"Да. При торможении модуль скорости уменьшается; направление ускорения противоположно направлению скорости."}],practice:"Рассчитай ускорение самоката, если его скорость увеличилась с 1 м/с до 7 м/с за 2 с.",steps:["Запиши начальную скорость v₀ = 1 м/с.","Запиши конечную скорость v = 7 м/с и время t = 2 с.","Используй формулу a = (v − v₀) / t.","Подставь значения и запиши результат в м/с²."],conclusion:"Ускорение характеризует изменение скорости. Оно может сопровождать как разгон, так и торможение.",question:"Скорость увеличилась с 4 м/с до 10 м/с за 2 с. Чему равно ускорение?",answers:["3 м/с²","7 м/с²","12 м/с²"],correct:0
}

,"Инерция":{
title:"Инерция",paragraph:"§ 19",chapter:"Глава 2 · Взаимодействие тел",lead:"Автобус резко тормозит, а пассажир наклоняется вперёд. Почему тело продолжает двигаться, хотя автобус уже замедляется?",short:"Инерция — явление сохранения скорости тела, когда действие других тел отсутствует или их действия скомпенсированы.",key:"Тело не изменяет свою скорость само по себе: для изменения скорости необходимо взаимодействие с другими телами.",explanation:["Если на тело не действуют другие тела или их действия скомпенсированы, тело сохраняет состояние покоя или равномерного прямолинейного движения. Это проявление инерции.","При торможении автобуса его скорость уменьшается. Тело пассажира стремится сохранить прежнюю скорость относительно дороги, поэтому относительно замедляющегося автобуса пассажир наклоняется вперёд. При начале движения автобуса пассажир может отклониться назад.","Инерция проявляется и в других ситуациях: шайба скользит по льду после толчка, мяч продолжает лететь после удара, груз на тележке смещается при её резкой остановке. В реальности движение постепенно меняется из-за трения и сопротивления воздуха.","Инерция не является отдельной силой. Это явление, описывающее сохранение скорости тела. Чем больше масса тела, тем труднее изменить его скорость при одинаковом воздействии; это свойство называют инертностью."],groups:[{name:"Покой",title:"Тело сохраняет состояние покоя",example:"Книга лежит на столе, пока взаимодействия не изменят её состояние."},{name:"Движение",title:"Тело сохраняет скорость",example:"Шайба продолжает скользить по гладкому льду после толчка."},{name:"Инертность",title:"Сопротивление изменению скорости",example:"Тяжёлую тележку труднее разогнать или остановить, чем лёгкую."}],observations:[{scene:"Автобус резко тормозит",prompt:"Почему пассажир наклоняется вперёд?",answer:"Пассажир стремится сохранить прежнюю скорость относительно дороги, тогда как автобус замедляется."},{scene:"Скатили мяч по полу",prompt:"Почему мяч постепенно останавливается?",answer:"На мяч действуют сила трения и сопротивление воздуха. Без этих воздействий он сохранял бы скорость."},{scene:"Пустая и загруженная тележки",prompt:"Какую труднее разогнать?",answer:"Обычно загруженную: у неё больше масса и инертность."}],practice:"Приведи два примера инерции из повседневной жизни. Для каждого укажи, какое тело сохраняет своё состояние движения и что изменяет движение.",steps:["Опиши ситуацию до изменения движения.","Укажи, какое тело стремится сохранить скорость.","Назови взаимодействие, которое изменяет движение.","Объясни результат, используя слово «инерция»."],conclusion:"Инерция объясняет, почему тела сохраняют покой или равномерное прямолинейное движение, если внешние воздействия отсутствуют или скомпенсированы.",question:"Почему при резком торможении автобуса пассажира наклоняет вперёд?",answers:["Пассажир стремится сохранить прежнюю скорость","На пассажира действует только сила тяжести","Автобус толкает пассажира вперёд отдельной силой"],correct:0
},
"Взаимодействие тел":{
title:"Взаимодействие тел",paragraph:"§ 20",chapter:"Глава 2 · Взаимодействие тел",lead:"Мяч меняет движение после удара, магнит притягивает скрепку, рука растягивает пружину. Изменения происходят при взаимодействии тел.",short:"Взаимодействие тел может изменить скорость, направление движения или форму тела.",key:"Изменение движения или деформация тела — признаки взаимодействия.",explanation:["Тела взаимодействуют друг с другом. Результатом взаимодействия может быть изменение скорости, направления движения или формы тела.","Когда нога ударяет по мячу, мяч изменяет скорость и направление. Когда рука сжимает губку, меняется её форма. Магнит может привести в движение расположенную рядом железную скрепку.","Взаимодействие всегда происходит между телами. Если тело А действует на тело Б, то и тело Б действует на тело А. Эти действия не следует представлять как одностороннее влияние.","Для количественного описания взаимодействия в физике используют понятие силы. Сила показывает, насколько сильно одно тело действует на другое; подробнее это понятие изучается в следующих темах."],groups:[{name:"Изменение скорости",title:"Тело разгоняется или тормозит",example:"Удар по мячу, торможение велосипеда."},{name:"Изменение направления",title:"Траектория меняется",example:"Ракетка отбивает теннисный мяч."},{name:"Деформация",title:"Изменяется форма тела",example:"Сжатие губки или растяжение пружины."}],observations:[{scene:"Мяч ударяется о стену",prompt:"Что изменяется?",answer:"Скорость и направление движения мяча меняются при взаимодействии со стеной."},{scene:"Сжимаем мягкую губку",prompt:"Как проявляется взаимодействие?",answer:"Рука действует на губку, и её форма изменяется."},{scene:"Магнит приближён к скрепке",prompt:"Может ли тело действовать без касания?",answer:"Да. Магнитное взаимодействие может происходить на расстоянии."}],practice:"Найди три примера взаимодействия: один с изменением скорости, один с изменением направления и один с деформацией.",steps:["Опиши два взаимодействующих тела.","Укажи, какое изменение наблюдается.","Определи, происходит ли контакт между телами.","Сделай вывод о результате взаимодействия."],conclusion:"Взаимодействие тел может изменять их движение и форму; для описания действия одного тела на другое вводят понятие силы.",question:"Какой пример показывает деформацию при взаимодействии?",answers:["Мяч катится по дорожке","Рука сжимает пружину","Свет отражается от зеркала"],correct:1
},
"Масса тела. Единицы массы":{
title:"Масса тела. Единицы массы",paragraph:"§ 21",chapter:"Глава 2 · Взаимодействие тел",lead:"Почему пустую тележку легче разогнать, чем такую же тележку с грузом? Масса связана с инертностью тела.",short:"Масса — физическая величина, характеризующая инертность тела. Основная единица массы в СИ — килограмм (кг).",key:"При одинаковом воздействии тело с большей массой изменяет скорость меньше.",explanation:["Масса характеризует инертность тела — его способность сопротивляться изменению скорости. Чем больше масса, тем труднее изменить скорость тела при одинаковом воздействии.","Основная единица массы в Международной системе единиц — килограмм (кг). Также используют грамм (г), миллиграмм (мг) и тонну (т). 1 кг = 1000 г; 1 г = 1000 мг; 1 т = 1000 кг.","Массу тела можно измерить с помощью весов. Важно отличать массу от веса: масса характеризует тело, а вес — силу, с которой тело вследствие притяжения действует на опору или подвес. Подробно вес рассматривается в теме о силах.","В медицине масса имеет практическое значение: массу пациента, лекарственного вещества или лабораторного образца измеряют с помощью соответствующих весов. При записи результата обязательно указывают единицу измерения."],groups:[{name:"Килограмм",title:"кг",example:"Основная единица массы в СИ."},{name:"Грамм",title:"г",example:"1 кг = 1000 г."},{name:"Тонна",title:"т",example:"1 т = 1000 кг."}],observations:[{scene:"Пустая и нагруженная тележки",prompt:"Какая тележка инертнее?",answer:"Нагруженная тележка имеет большую массу, поэтому при одинаковом воздействии её скорость изменить труднее."},{scene:"На упаковке указано 250 г",prompt:"Сколько это килограммов?",answer:"250 г = 0,25 кг, потому что 1 кг содержит 1000 г."}],practice:"Выполни переводы: 3,5 кг в граммы; 750 г в килограммы; 2 т в килограммы.",steps:["Вспомни соотношения между единицами массы.","При переходе от килограммов к граммам умножай на 1000.","При переходе от граммов к килограммам дели на 1000.","Запиши результат вместе с единицей измерения."],conclusion:"Масса характеризует инертность тела и измеряется в килограммах и других единицах массы.",question:"Какова масса 750 г в килограммах?",answers:["7,5 кг","0,75 кг","75 кг"],correct:1
}
,"Измерение массы тела на весах":{
title:"Измерение массы тела на весах",paragraph:"§ 22",chapter:"Глава 2 · Взаимодействие тел",lead:"Массу тела можно определить с помощью весов. Важно выбрать подходящий прибор и правильно прочитать его показания.",short:"Массу измеряют весами. Результат записывают числом с единицей измерения.",key:"Перед измерением проверь нулевое положение весов, выбери подходящий диапазон и считай показание после установления равновесия.",explanation:["Для измерения массы используют рычажные, электронные и другие виды весов. Принцип работы разных приборов отличается, но цель одна — определить массу тела.","Перед измерением проверь, что весы установлены ровно и показывают ноль без груза. Если предусмотрена настройка нуля, выполни её согласно инструкции прибора.","Положи тело на платформу или чашу весов, не опирайся на стол и дождись устойчивого показания. Запиши результат вместе с единицей измерения: граммами или килограммами.","При работе с лабораторными весами нельзя перегружать прибор, класть на платформу горячие, мокрые или загрязняющие её предметы. Для точного результата учитывай цену деления и возможную погрешность."],groups:[{name:"Подготовка",title:"Проверь ноль",example:"Пустые весы должны показывать нулевое значение."},{name:"Измерение",title:"Размести тело",example:"Положи объект в центр платформы."},{name:"Запись",title:"Число и единица",example:"Масса образца — 125 г."}],observations:[{scene:"Электронные весы показывают 0,250 кг",prompt:"Как записать результат в граммах?",answer:"0,250 кг = 250 г."},{scene:"После установки груза показания меняются",prompt:"Когда записывать результат?",answer:"Когда показания стабилизировались."}],practice:"Представь, что измеряешь массу небольшого предмета. Составь алгоритм измерения и укажи, какие ошибки могут повлиять на результат.",steps:["Проверь нулевое показание весов.","Размести предмет на платформе или чаше.","Дождись устойчивого показания.","Запиши массу и единицу измерения."],conclusion:"Точность измерения зависит от правильной подготовки весов, аккуратного размещения тела и корректного считывания показаний.",question:"Что нужно сделать перед измерением массы на электронных весах?",answers:["Проверить нулевое показание","Положить на весы сразу несколько тяжёлых предметов","Наклонить весы"],correct:0
},
"Плотность вещества":{
title:"Плотность вещества",paragraph:"§ 23",chapter:"Глава 2 · Взаимодействие тел",lead:"Кусок железа и кусок дерева одинакового объёма могут иметь разную массу. Плотность показывает, какая масса приходится на единицу объёма.",short:"Плотность вещества равна отношению массы тела к его объёму.",key:"Плотность обозначают греческой буквой ρ (ро). Формула: ρ = m / V. Здесь ρ — плотность (кг/м³), m — масса (кг), V — объём (м³).",explanation:["Плотность — физическая величина, характеризующая массу вещества в единице объёма. Если два тела имеют одинаковый объём, но сделаны из разных веществ, их массы могут различаться.","Плотность вычисляют по формуле: ρ = m / V. Здесь ρ — плотность (читается «ро», килограмм на кубический метр, кг/м³); m — масса (килограмм, кг); V — объём (кубический метр, м³).","Часто плотность выражают в г/см³. Связь единиц: 1 г/см³ = 1000 кг/м³. Например, плотность воды приблизительно равна 1 г/см³, или 1000 кг/м³, при обычных школьных условиях.","Чтобы найти плотность тела, нужно измерить его массу и объём. Массу можно определить весами. Объём правильного тела можно вычислить по размерам, а объём тела неправильной формы — определить методом вытеснения жидкости, если материал не растворяется и не взаимодействует с ней.","Плотность зависит от вещества и условий, в частности температуры. Поэтому табличные значения используют как ориентир, а в эксперименте обязательно указывают единицы и условия измерения."],groups:[{name:"Формула",title:"ρ = m / V",example:"Массу делят на объём."},{name:"Единица СИ",title:"кг/м³",example:"Килограмм на кубический метр."},{name:"Другая единица",title:"г/см³",example:"1 г/см³ = 1000 кг/м³."}],observations:[{scene:"Два кубика одинакового объёма",prompt:"У одного масса больше. Что можно предположить?",answer:"У него больше плотность, если объёмы кубиков действительно одинаковы."},{scene:"Масса образца 200 г, объём 100 см³",prompt:"Какова плотность?",answer:"ρ = 200 г / 100 см³ = 2 г/см³."}],practice:"Рассчитай плотность образца массой 150 г и объёмом 50 см³. Запиши формулу, расшифруй обозначения и укажи единицу результата.",steps:["Запиши массу m = 150 г и объём V = 50 см³.","Используй формулу ρ = m / V.","Раздели массу на объём.","Запиши плотность в г/см³."],conclusion:"Плотность связывает массу вещества с занимаемым объёмом и помогает сравнивать вещества.",question:"Какова плотность тела массой 60 г и объёмом 20 см³?",answers:["3 г/см³","40 г/см³","1200 г/см³"],correct:0
},
"Расчёт массы и объёма тела по его плотности":{
title:"Расчёт массы и объёма тела по его плотности",paragraph:"§ 24",chapter:"Глава 2 · Взаимодействие тел",lead:"Если известны плотность вещества и объём тела, можно найти его массу. Если известны масса и плотность — вычислить объём.",short:"Из формулы плотности получают две формулы: m = ρ · V и V = m / ρ.",key:"m — масса (кг или г); ρ — плотность (кг/м³ или г/см³); V — объём (м³ или см³). Используй согласованные единицы.",explanation:["Основная формула плотности: ρ = m / V. Если нужно найти массу, обе части соотношения преобразуют: m = ρ · V.","Если нужно найти объём, используют формулу V = m / ρ. Здесь V — объём (м³ или см³), m — масса (кг или г), ρ — плотность (кг/м³ или г/см³).","Пример расчёта массы: объём алюминиевого образца 100 см³, плотность условно принимаем 2,7 г/см³. Тогда m = 2,7 · 100 = 270 г. Единицы согласованы: г/см³ умножаем на см³ и получаем граммы.","Пример расчёта объёма: масса образца 540 г, плотность 2,7 г/см³. Тогда V = 540 / 2,7 = 200 см³.","Перед вычислением проверь единицы. Нельзя без перевода умножать плотность в кг/м³ на объём в см³. Сначала приведи величины к одной системе единиц."],groups:[{name:"Найти массу",title:"m = ρ · V",example:"Плотность умножить на объём."},{name:"Найти объём",title:"V = m / ρ",example:"Массу разделить на плотность."},{name:"Проверка",title:"Согласуй единицы",example:"г/см³ × см³ = г; кг/м³ × м³ = кг."}],observations:[{scene:"Плотность 2 г/см³, объём 30 см³",prompt:"Какова масса?",answer:"m = 2 · 30 = 60 г."},{scene:"Масса 90 г, плотность 3 г/см³",prompt:"Каков объём?",answer:"V = 90 / 3 = 30 см³."}],practice:"Реши две задачи: 1) плотность вещества 4 г/см³, объём тела 25 см³ — найди массу; 2) масса тела 120 г, плотность 2 г/см³ — найди объём.",steps:["Для первой задачи выбери формулу m = ρ · V.","Для второй задачи выбери формулу V = m / ρ.","Проверь, что единицы плотности и объёма согласованы.","Выполни вычисления и запиши ответы с единицами."],conclusion:"Формулы плотности позволяют находить массу и объём, если известны две другие величины.",question:"Как найти объём тела, если известны масса и плотность?",answers:["V = m · ρ","V = ρ / m","V = m / ρ"],correct:2
}


};